import Foundation

struct ShoppingItem: Codable, Identifiable {
    let id: String
    let listId: String
    let familyId: String
    var name: String
    var quantity: String?
    var category: String
    var isChecked: Bool
    var checkedBy: String?
    var checkedAt: Date?
    let createdBy: String
    let createdAt: Date
    let updatedAt: Date
}

enum ShoppingCategory: String, CaseIterable {
    case produce    = "produce"
    case vegetables = "vegetables"
    case fruits     = "fruits"
    case dairy      = "dairy"
    case eggs       = "eggs"
    case meat       = "meat"
    case bakery     = "bakery"
    case grains     = "grains"
    case canned     = "canned"
    case condiments = "condiments"
    case household   = "household"
    case personalCare = "personal_care"
    case frozen      = "frozen"
    case beverages  = "beverages"
    case snacks     = "snacks"
    case other      = "other"

    var emoji: String {
        switch self {
        case .produce:    return "🥦"
        case .vegetables: return "🥬"
        case .fruits:     return "🍎"
        case .dairy:      return "🥛"
        case .eggs:       return "🥚"
        case .meat:       return "🥩"
        case .bakery:     return "🧁"
        case .grains:     return "🌾"
        case .canned:     return "🥫"
        case .condiments: return "🧂"
        case .household:    return "🧹"
        case .personalCare: return "🧴"
        case .frozen:       return "❄️"
        case .beverages:  return "🧃"
        case .snacks:     return "🍿"
        case .other:      return "📦"
        }
    }

    var displayName: String {
        switch self {
        case .produce:    return "Fresh Produce"
        case .vegetables: return "Vegetables"
        case .fruits:     return "Fruits"
        case .dairy:      return "Dairy & Eggs"
        case .eggs:       return "Eggs"
        case .meat:       return "Meat & Fish"
        case .bakery:     return "Bakery"
        case .grains:     return "Grains & Pasta"
        case .canned:     return "Canned Goods"
        case .condiments: return "Condiments & Sauces"
        case .household:  return "Household"
        case .personalCare: return "Personal Care"
        case .frozen:     return "Frozen Foods"
        case .beverages:  return "Beverages"
        case .snacks:     return "Snacks"
        case .other:      return "Other"
        }
    }

    static func detect(from name: String) -> ShoppingCategory {
        let n = name.lowercased()

        // Exact matches first (highest priority)
        let exactMatches: [String: ShoppingCategory] = [
            "egg": .eggs, "eggs": .eggs,
            "milk": .dairy, "cheese": .dairy, "yogurt": .dairy,
            "bread": .bakery, "rice": .grains, "pasta": .grains,
            "chicken": .meat, "beef": .meat, "salmon": .meat,
            "apple": .fruits, "banana": .fruits, "orange": .fruits,
            "spinach": .vegetables, "carrot": .vegetables, "broccoli": .vegetables,
            "water": .beverages, "coffee": .beverages, "juice": .beverages,
            "chips": .snacks, "cookies": .snacks, "chocolate": .snacks,
            "shampoo": .personalCare, "soap": .household, "detergent": .household,
            "pizza": .frozen, "ice cream": .frozen,
        ]

        if let exact = exactMatches[n] { return exact }

        // Category keyword lists (contains matches)
        let categories: [(ShoppingCategory, [String])] = [
